// Package app owns the top-level dependency wiring for the IAM process.
package app

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"

	"benchmark.local/iam/internal/config"
	"benchmark.local/iam/internal/domain"
	"benchmark.local/iam/internal/repository"
	"benchmark.local/iam/internal/security"
)

const MaxRequestBodyBytes int64 = 1 << 20

type App struct {
	Config config.Config
	Clock  domain.Clock
	Users  *repository.UserRepository
}

func New(cfg config.Config) (*App, error) {
	return NewWithClock(cfg, domain.SystemClock{})
}

func NewWithClock(cfg config.Config, clock domain.Clock) (*App, error) {
	if err := cfg.Validate(); err != nil {
		return nil, err
	}
	if clock == nil {
		return nil, domain.Invalid("clock must not be nil")
	}
	return &App{Config: cfg, Clock: clock, Users: repository.NewUserRepository()}, nil
}

func (a *App) Handler() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("POST /v1/register", a.register)
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		writeData(w, http.StatusOK, map[string]string{"status": "ok"})
	})
	mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, _ *http.Request) {
		writeData(w, http.StatusOK, map[string]string{"status": "ready"})
	})
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		r.Body = http.MaxBytesReader(w, r.Body, MaxRequestBodyBytes)
		mux.ServeHTTP(w, r)
	})
}

type registerRequest struct {
	Email    string `json:"email"`
	Password string `json:"password"`
}

func (a *App) register(w http.ResponseWriter, r *http.Request) {
	var request registerRequest
	if err := decodeJSON(r, &request); err != nil {
		if _, tooLarge := err.(*http.MaxBytesError); tooLarge {
			writeError(w, http.StatusRequestEntityTooLarge, "body_too_large", "request body is too large")
			return
		}
		writeError(w, http.StatusBadRequest, "invalid_request", "request body is invalid")
		return
	}
	email, err := domain.NormalizeEmail(request.Email)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_email", "email is invalid")
		return
	}
	material, err := security.HashPassword(request.Password)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_password", "password does not meet policy")
		return
	}
	id, err := domain.NewUserID()
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", "unable to create user")
		return
	}
	now := a.Clock.Now()
	user := domain.User{
		ID:                id,
		Email:             domain.Email(email),
		EmailVerification: domain.EmailUnverified,
		PasswordMaterial:  material,
		CreatedAt:         now,
		UpdatedAt:         now,
	}
	if err := a.Users.Create(user); err != nil {
		if errors.Is(err, domain.ErrConflict) {
			writeError(w, http.StatusConflict, "conflict", "email is already registered")
			return
		}
		writeError(w, http.StatusBadRequest, "invalid_request", "user could not be created")
		return
	}
	writeData(w, http.StatusCreated, user.PublicProfile())
}

func decodeJSON(r *http.Request, dst any) error {
	decoder := json.NewDecoder(r.Body)
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(dst); err != nil {
		return err
	}
	var extra any
	if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
		if err == nil {
			return errors.New("multiple JSON values")
		}
		return err
	}
	return nil
}

func writeData(w http.ResponseWriter, status int, data any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(map[string]any{"data": data})
}

func writeError(w http.ResponseWriter, status int, code, message string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(map[string]any{
		"error": map[string]string{
			"code":    code,
			"message": message,
		},
	})
}
